using System;
using System.IO;
using System.Drawing;
using System.Drawing.Imaging;
using System.Collections.Generic;
using System.Text;
public class GraffitiAssembler {
static string root, dest; static Color[] pal; static Color bg=Color.FromArgb(255,25,24,31);
static Color Q(Color c) { int d=int.MaxValue; Color best=pal[0]; foreach(var p in pal){int n=(c.R-p.R)*(c.R-p.R)+(c.G-p.G)*(c.G-p.G)+(c.B-p.B)*(c.B-p.B);if(n<d){d=n;best=p;}}return best; }
static Bitmap Blank(int w,int h){var b=new Bitmap(w,h,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(b))g.Clear(bg);return b;}
static void Paste(Bitmap d,Bitmap s,int dx,int dy){using(var g=Graphics.FromImage(d))g.DrawImageUnscaled(s,dx,dy);}
static Bitmap Crop(Bitmap s,int x,int y,int w,int h){return s.Clone(new Rectangle(x,y,w,h),PixelFormat.Format32bppArgb);}
static Bitmap Scale(Bitmap b,int k){var o=Blank(b.Width*k,b.Height*k);using(var g=Graphics.FromImage(o)){g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;g.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.Half;g.DrawImage(b,new Rectangle(0,0,o.Width,o.Height),0,0,b.Width,b.Height,GraphicsUnit.Pixel);}return o;}
static void Save(Bitmap b,string p){b.Save(Path.Combine(dest,p),ImageFormat.Png);}
static Bitmap[,] Sample(string file){var s=new Bitmap(file);var t=new Bitmap[3,3];for(int a=0;a<3;a++)for(int b=0;b<3;b++){t[a,b]=Blank(32,32);for(int y=0;y<32;y++)for(int x=0;x<32;x++){int sx=(int)((b+(x+0.5)/32)*s.Width/3);int sy=(int)((a+(y+0.5)/32)*s.Height/3);t[a,b].SetPixel(x,y,Q(s.GetPixel(sx,sy)));}}s.Dispose();return t;}
static uint H(int x,int y){unchecked{uint h=(uint)(x*73856093)^(uint)(y*19349663);h^=h>>13;h*=0x5bd1e995;h^=h>>15;return h;}}
static int Kind(int x,int y){return (int)(H(x,y)%3);}
static Color BuildColor(Color c){var opts=new Color[]{ColorTranslator.FromHtml("#303940"),ColorTranslator.FromHtml("#3B454C"),ColorTranslator.FromHtml("#47525A"),ColorTranslator.FromHtml("#55616A"),ColorTranslator.FromHtml("#65717A"),ColorTranslator.FromHtml("#75818A"),ColorTranslator.FromHtml("#89959D")};double l=.2126*c.R+.7152*c.G+.0722*c.B;double target=55+l*.30;int best=0;double err=999;for(int i=0;i<opts.Length;i++){double v=.2126*opts[i].R+.7152*opts[i].G+.0722*opts[i].B; if(Math.Abs(target-v)<err){err=Math.Abs(target-v);best=i;}}return opts[best];}
static Bitmap[,] Build(Bitmap[,] a){var t=new Bitmap[3,3];for(int i=0;i<3;i++)for(int j=0;j<3;j++){t[i,j]=Blank(32,32);for(int y=0;y<32;y++)for(int x=0;x<32;x++)t[i,j].SetPixel(x,y,BuildColor(a[i,j].GetPixel(x,y)));}return t;}
static bool Paint(Color c){return c.R>c.G*1.25 && c.R>85 || c.R>185 && c.G>175 && c.B>165;}
static void Export(Bitmap[,] t,string kind,string sub){for(int i=0;i<3;i++)for(int j=0;j<3;j++)Save(t[i,j],"_1x/"+sub+kind+(kind=="Floor"?"_L":"_T")+i+(kind=="Floor"?"_R":"_B")+j+".png");}
static void Sheet(Bitmap[,] t,string kind){var s=Blank(580,580);for(int i=0;i<3;i++)for(int j=0;j<3;j++)using(var z=Scale(t[i,j],6))Paste(s,z,j*194,i*194);Save(s,"Sheet_"+kind+"_6x.png");s.Dispose();}
static long Check(Bitmap[,] t,bool wall){long n=0;for(int k=0;k<3;k++)for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int z=0;z<32;z++)for(int d=0;d<2;d++){var c=wall?t[a,k].GetPixel(z,30+d):t[a,k].GetPixel(30+d,z);var e=wall?t[k,b].GetPixel(z,d):t[k,b].GetPixel(d,z);if(c.ToArgb()==e.ToArgb())n++;}return n;}
static bool Connected(Bitmap b,bool wall){var seen=new bool[32,32];var q=new Queue<Point>();for(int z=0;z<32;z++){int x=wall?z:0,y=wall?0:z;if((wall||y>=4)&&Paint(b.GetPixel(x,y))){seen[x,y]=true;q.Enqueue(new Point(x,y));}}while(q.Count>0){var p=q.Dequeue();if((wall?p.Y:p.X)==31)return true;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int x=p.X+dx,y=p.Y+dy;if(x>=0&&x<32&&y>=(wall?0:4)&&y<32&&!seen[x,y]&&Paint(b.GetPixel(x,y))){seen[x,y]=true;q.Enqueue(new Point(x,y));}}}return false;}
public static void Run(string repo,string floor,string wall,int[] grid,int width,int height,int[] slots,int spawnX,int spawnY){root=repo;dest=Path.Combine(root,"NEWIMAG/GraffitiTiles");Directory.CreateDirectory(Path.Combine(dest,"_1x/Build"));Directory.CreateDirectory(Path.Combine(dest,"Sources"));Directory.CreateDirectory(Path.Combine(dest,"Edges"));
var colors=new List<Color>();foreach(var file in new[]{"NEWIMAG/palette_v2.txt","NEWIMAG/TileConceptV2/A/palette_add_A.txt"})foreach(string l in File.ReadAllLines(Path.Combine(root,file)))if(System.Text.RegularExpressions.Regex.IsMatch(l.Trim(),"^#[0-9a-fA-F]{6}$"))colors.Add(ColorTranslator.FromHtml(l.Trim()));
// One shared subset prevents seam repair from increasing a tile past 24 colors.
var wanted=new HashSet<string>(new[]{"#19181F","#2A282D","#303940","#3B454C","#47525A","#55616A","#65717A","#75818A","#89959D","#9CA7AC","#641F36","#92223F","#B83450","#DC526B","#E7D8CE","#F7EEE4"});colors.RemoveAll(c=>!wanted.Contains("#"+c.R.ToString("X2")+c.G.ToString("X2")+c.B.ToString("X2")));pal=colors.ToArray();
if(!String.Equals(Path.GetFullPath(floor),Path.GetFullPath(Path.Combine(dest,"Sources/Floor_selected.png")),StringComparison.OrdinalIgnoreCase))File.Copy(floor,Path.Combine(dest,"Sources/Floor_selected.png"),true);if(!String.Equals(Path.GetFullPath(wall),Path.GetFullPath(Path.Combine(dest,"Sources/Wall_selected.png")),StringComparison.OrdinalIgnoreCase))File.Copy(wall,Path.Combine(dest,"Sources/Wall_selected.png"),true);
var f=Sample(floor);var w=Sample(wall);
// Cut-and-paste translation: Wall 0->1 generated bottom port is 3px too far right.
var shifted=Blank(32,32);for(int y=0;y<32;y++)for(int x=0;x<32;x++)shifted.SetPixel(x,y,w[0,1].GetPixel(x<29?x+3:x-29,y));w[0,1]=shifted;
var aFloor=new Bitmap(Path.Combine(root,"NEWIMAG/TileConceptV2/A/_1x/Tile_Play_Floor.png"));for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int y=0;y<3;y++)for(int x=0;x<32;x++)f[a,b].SetPixel(x,y,Q(aFloor.GetPixel(x,y)));
var edgeText=new StringBuilder();edgeText.AppendLine("Coordinates are zero-based; Floor rows top-to-bottom, Wall columns left-to-right. Each sampled 1px profile is duplicated into both boundary pixels. Hex colors are final palette-mapped source pixels.");
for(int k=0;k<3;k++){int sx=k==0?2:2;var ef=Blank(2,32);var ew=Blank(32,2);for(int z=0;z<32;z++){Color cf=f[k,k].GetPixel(sx,z);Color cw=w[k,k].GetPixel(z,2);for(int d=0;d<2;d++){ef.SetPixel(d,z,cf);ew.SetPixel(z,d,cw);}edgeText.AppendLine("Floor "+k+" row "+z+": #"+cf.R.ToString("X2")+cf.G.ToString("X2")+cf.B.ToString("X2")+" | Wall "+k+" column "+z+": #"+cw.R.ToString("X2")+cw.G.ToString("X2")+cw.B.ToString("X2"));}Save(ef,"Edges/Floor_"+k+".png");Save(ew,"Edges/Wall_"+k+".png");for(int a=0;a<3;a++){Paste(f[k,a],ef,0,0);Paste(f[a,k],ef,30,0);Paste(w[k,a],ew,0,0);Paste(w[a,k],ew,0,30);}}
File.WriteAllText(Path.Combine(dest,"Edges/profiles.txt"),edgeText.ToString());
// Retry nearby grid-center registrations when a subpixel source grid drops a thin stroke.
string registration="Floor22 initial center registration";
if(!Connected(f[2,2],false)){using(var src=new Bitmap(floor)){bool found=false;for(int radius=1;radius<=8&&!found;radius++)for(int dy=-radius;dy<=radius&&!found;dy++)for(int dx=-radius;dx<=radius&&!found;dx++){if(Math.Max(Math.Abs(dx),Math.Abs(dy))!=radius)continue;var candidate=(Bitmap)f[2,2].Clone();for(int y=3;y<32;y++)for(int x=2;x<30;x++){int sx=Math.Min(src.Width-1,Math.Max(0,(int)((2+(x+.5)/32)*src.Width/3)+dx));int sy=Math.Min(src.Height-1,Math.Max(0,(int)((2+(y+.5)/32)*src.Height/3)+dy));candidate.SetPixel(x,y,Q(src.GetPixel(sx,sy)));}if(Connected(candidate,false)){f[2,2]=candidate;found=true;registration="Floor22 grid center registration offset: "+dx+","+dy+" source pixels (source cell approx 418px).";}else candidate.Dispose();}}}
File.WriteAllText(Path.Combine(dest,"sampling.txt"),registration);
var fb=Build(f);var wb=Build(w);Export(f,"Floor","");Export(w,"Wall","");Export(fb,"Floor","Build/");Export(wb,"Wall","Build/");Sheet(f,"Floor");Sheet(w,"Wall");
var strip=Blank(768,112);var stripB=Blank(768,112);int[] ys={0,7,19};var seq=new StringBuilder();for(int row=0;row<3;row++){seq.Append("y="+ys[row]+": ");for(int x=0;x<24;x++){int l=x==0?0:Kind(x-1,ys[row]);int r=x==23?0:Kind(x,ys[row]);Paste(strip,f[l,r],x*32,row*40);Paste(stripB,fb[l,r],x*32,row*40);seq.Append(l+""+r+" ");}seq.AppendLine();}using(var z=Scale(strip,3))Save(z,"Strip_3x.png");using(var z=Scale(stripB,3))Save(z,"Strip_Build_3x.png");File.WriteAllText(Path.Combine(dest,"strip_sequence.txt"),seq.ToString());
var vs=Blank(112,768);for(int col=0;col<3;col++)for(int y=0;y<24;y++){int t=y==23?0:Kind(ys[col],y);int b=y==0?0:Kind(ys[col],y-1);Paste(vs,w[t,b],col*40,(23-y)*32);}using(var z=Scale(vs,3))Save(z,"Strip_Wall_3x.png");
var terrain=(int[])grid.Clone();for(int i=0;i<slots.Length;i+=3)terrain[slots[i+1]*width+slots[i]]=slots[i+2];Func<int,int,int> cell=(x,y)=>x<0||x>=width||y<0||y>=height?0:terrain[y*width+x];
// Camera 640x360, bottom-left world crop; spawn near lower left as in the reference.
var mock=Blank(640,360);for(int y=0;y<height;y++)for(int x=0;x<width;x++){int v=cell(x,y);if(v==0)continue;Bitmap tile;if(v==2){int t=cell(x,y+1)==v?Kind(x,y):0;int b=cell(x,y-1)==v?Kind(x,y-1):0;tile=w[t,b];}else{int l=cell(x-1,y)==v?Kind(x-1,y):0;int r=cell(x+1,y)==v?Kind(x,y):0;tile=f[l,r];}Paste(mock,tile,x*32,360-(y+1)*32);}
var heroSheet=new Bitmap(Path.Combine(root,"NEWIMAG/Px32HeroV2/_1x/Hero_Idle.png"));var hero=Crop(heroSheet,0,0,96,96);int foot=95;for(int y=95;y>=0;y--){bool any=false;for(int x=0;x<96;x++)if(hero.GetPixel(x,y).A>20)any=true;if(any){foot=y;break;}}int floorY=spawnY-1;while(floorY>=0&&cell(spawnX,floorY)==0)floorY--;int screenFoot=360-(floorY+1)*32;Paste(mock,hero,spawnX*32+16-48,screenFoot-foot-1);var mock3=Scale(mock,3);Save(mock3,"Mock_3x.png");
var old=new Bitmap(Path.Combine(root,"NEWIMAG/TileConceptV2/A/Mock_Play_3x.png"));var comp=Blank(1920,2256);Paste(comp,old,0,48);Paste(comp,mock3,0,1176);using(var g=Graphics.FromImage(comp))using(var font=new Font("Malgun Gothic",23,FontStyle.Bold,GraphicsUnit.Pixel)){g.DrawString("\uc774\uc804: \ub3c4\uc7a5 \ubc18\ubcf5",font,Brushes.White,20,9);g.DrawString("\uc0c8: \uc774\uc5b4\uc9c0\ub294 \ub099\uc11c",font,Brushes.White,20,1137);}Save(comp,"Compare_3x.png");
var report=new StringBuilder();report.AppendLine("Boundary 2px paired RGBA pixels: Floor "+Check(f,false)+"/1728; Wall "+Check(w,true)+"/1728; Build Floor "+Check(fb,false)+"/1728; Build Wall "+Check(wb,true)+"/1728.");int max=0;foreach(var set in new[]{f,w,fb,wb})foreach(var tile in set){var cs=new HashSet<int>();for(int y=0;y<32;y++)for(int x=0;x<32;x++){var c=tile.GetPixel(x,y);if(c.A!=255)throw new Exception("alpha");if(!colors.Exists(p=>p.ToArgb()==c.ToArgb()))throw new Exception("Palette mismatch: "+c);cs.Add(c.ToArgb());}max=Math.Max(max,cs.Count);}report.AppendLine("All 36 tiles: 32x32, alpha 255. Maximum colors: "+max+".");for(int a=1;a<3;a++)for(int b=1;b<3;b++)report.AppendLine("8-neighbor paint connectivity Floor "+a+b+": "+Connected(f[a,b],false)+"; Wall "+a+b+": "+Connected(w[a,b],true));report.AppendLine("Map dimensions "+width+"x"+height+"; trapSlots "+slots.Length/3+"; spawn "+spawnX+","+spawnY+"; camera world x=[0,640), y=[0,360). Hero visible foot y="+screenFoot+".");File.WriteAllText(Path.Combine(dest,"validation.txt"),report.ToString());Console.WriteLine(report);
}
}
